"""Original urinary infection half, using 2025 IDSA and 2026 EAU guidance."""
from qbank_authoring import question,ref,finalize
UT=ref('IDSA Complicated UTI Guideline, 2025','https://www.idsociety.org/practice-guideline/complicated-urinary-tract-infections')
AS=ref('IDSA Asymptomatic Bacteriuria Guideline','https://www.idsociety.org/practice-guideline/asymptomatic-bacteriuria/')
EA=ref('EAU Guidelines on Urological Infections, 2026','https://uroweb.org/guidelines/urological-infections/chapter/the-guideline')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Under the revised 2025 IDSA classification, which feature most directly suggests UTI has extended beyond the bladder?', 'Fever or other systemic features compatible with an upper/systemic urinary infection',[
 ('Male sex alone in an otherwise localized bladder syndrome','The revised approach focuses on extent and symptoms rather than classifying by sex alone.'),('Any positive culture without symptoms','This may represent asymptomatic bacteriuria.'),('Urine odor alone','This is not reliable evidence of systemic infection.')],
 'The newer classification emphasizes the clinical extent of infection', '**Localized cystitis and infection beyond the bladder need different assessment.**',['Fever, flank pain and systemic illness are important clues.','Host and anatomical factors still influence treatment risk.'], '**Use the syndrome to guide agent, route and source evaluation.**',['Do not treat a culture label without clinical attribution.','Shock or obstruction requires urgent management.'],[['Bladder-localized','Lower urinary symptoms'],['Beyond bladder','Fever or systemic/upper-tract features'],['Risk modifiers','Still important for management']],[UT])
q('A patient has fever, flank tenderness and pyelonephritis. Why is nitrofurantoin an inappropriate treatment choice?', 'It does not provide adequate renal-tissue/systemic exposure for upper-tract infection',[
 ('It never reaches the urine','Its urinary concentration is the basis of its cystitis role.'),('It is a universal cause of immediate allergy in all patients','That is not the reason for the site limitation.'),('Every organism causing pyelonephritis is inherently resistant to it','Even in-vitro susceptibility would not solve inadequate tissue exposure.')],
 'Susceptibility alone is insufficient when the drug does not reach the infected site', '**Nitrofurantoin is used for selected lower-tract infections.**',['Pyelonephritis requires an agent with suitable renal/systemic exposure.','Sepsis can require initial IV therapy.'], '**Select treatment by site, severity and susceptibility.**',['Obtain an appropriate urine culture.','Assess obstruction and complications when indicated.'],[['Cystitis','Urine exposure can suffice'],['Pyelonephritis','Renal-tissue exposure required'],['Choice','Drug plus site plus susceptibility']],[EA,UT],style='clinical_scenario')
q('Which patient generally should be screened for and treated for asymptomatic bacteriuria?', 'A pregnant patient under the antenatal screening pathway',[
 ('A nonpregnant adult with well-controlled diabetes and no urinary symptoms','Routine treatment is not recommended solely for diabetes.'),('Every long-term catheter user with no attributable symptoms','Colonization is common and routine treatment is usually harmful.'),('Every healthy nonpregnant adult with a positive incidental culture','Routine treatment is not indicated.')],
 'ASB treatment is limited to selected evidence-based settings', '**Pregnancy is an important exception to routine nontreatment.**',['Use a pregnancy-appropriate susceptibility-directed drug.','Endourologic procedures with mucosal trauma are another important indication.'], '**Do not generalize the exception to all positive urine cultures.**',['Unnecessary treatment increases adverse effects and resistance.','Assess true symptoms and systemic findings before labeling infection.'],[['Pregnancy','Screen/treat according to guidance'],['Diabetes alone','No routine ASB treatment'],['Long-term catheter','No routine treatment of colonization']],[AS])
q('An afebrile nonpregnant patient with diabetes has an incidental positive urine culture but no urinary symptoms. What is generally appropriate?', 'Do not prescribe antibiotics solely for the asymptomatic bacteriuria',[
 ('Treat every positive culture because diabetes makes all bacteriuria symptomatic','Symptoms and context still determine infection.'),('Use indefinite suppressive antibiotics automatically','This is not recommended routinely.'),('Order repeated test-of-cure cultures until all growth disappears','This can perpetuate unnecessary treatment.')],
 'A risk factor is not itself an infection diagnosis', '**Routine ASB treatment in diabetes has no established net benefit.**',['Antibiotics can cause adverse effects and select resistance.','Pregnancy or an indicated urological procedure changes the context.'], '**Explain why a culture result does not mandate treatment.**',['Provide advice about symptoms that should prompt reassessment.','Avoid repeat cultures without a clinical indication.'],[['Finding','Bacteriuria without symptoms'],['Routine response','No antibiotics'],['Exceptions','Assess specific guideline indications']],[AS],style='clinical_scenario')
q('A patient with ASB is scheduled for an endourological procedure expected to cause mucosal trauma. What is appropriate?', 'Obtain a urine culture and provide appropriately targeted peri-procedural treatment',[
 ('Ignore bacteriuria because ASB is never treated','This is a recognized procedural exception.'),('Use a prolonged empirical course for every future month','Treatment should be procedure-specific and limited.'),('Use an unrelated antibiotic without reference to susceptibility','Targeted therapy is preferred when results are available.')],
 'Instrumenting colonized tissue can create a bloodstream-infection risk', '**Mucosal-trauma procedures are an important ASB treatment indication.**',['The culture guides agent selection.','The recommended course is short and timed to the procedure in the appropriate pathway.'], '**Coordinate with the procedural team.**',['Distinguish this from low-risk procedures without mucosal trauma.','Review allergy, renal function and local policy.'],[['Risk','Procedure-related bacteremia/sepsis'],['Selection','Culture-directed'],['Duration','Short procedure-timed course']],[AS])
q('A patient with a long-standing urinary catheter develops a convincing catheter-associated UTI syndrome. Which source-management principle is appropriate?', 'Remove an unnecessary catheter or replace it when indicated, and obtain a suitable urine specimen',[
 ('Culture only the collection bag and treat any growth','Bag specimens are not the appropriate diagnostic sample.'),('Leave every catheter unchanged regardless of need or duration','The device can sustain infection.'),('Treat cloudy urine alone as proof of symptomatic infection','Appearance does not establish the syndrome.')],
 'The device affects both infection persistence and specimen validity', '**Assess whether catheterization is still necessary.**',['Replacement can help management in the appropriate established-catheter setting.','Obtain the specimen through the recommended method, often from a new catheter when replaced.'], '**Treat the clinical infection with a suitable agent.**',['Do not conflate colonization with symptomatic CAUTI.','Review the patient for alternative sources of fever.'],[['Device','Remove or replace when indicated'],['Specimen','Use a valid collection method'],['Diagnosis','Clinical syndrome plus supporting evidence']],[EA],style='clinical_scenario')
q('A febrile hypotensive patient has an obstructing ureteric stone and hydronephrosis. What is essential in addition to antibiotics and resuscitation?', 'Urgent decompression of the infected obstructed urinary system',[
 ('Wait for spontaneous stone passage regardless of shock','Persistent obstruction can sustain sepsis.'),('Perform definitive elective stone fragmentation before addressing the infected system in every case','Immediate drainage and stabilization take priority.'),('Use an antipyretic as a substitute for source control','It does not relieve obstruction.')],
 'An infected obstructed system is a source-control emergency', '**Drainage can be achieved by an appropriate stent or nephrostomy approach.**',['The method depends on anatomy, resources and expertise.','Definitive stone treatment is planned after infection control when appropriate.'], '**Coordinate urological intervention promptly.**',['Obtain suitable cultures without delaying care.','Monitor renal function and hemodynamic response.'],[['Problem','Infection behind obstruction'],['Immediate source control','Decompression'],['Later','Definitive stone management']],[EA],style='clinical_scenario')
q('A man has fever, dysuria, pelvic pain and a tender prostate. Which examination maneuver should be avoided in suspected acute bacterial prostatitis?', 'Vigorous prostatic massage',[
 ('Gentle appropriate clinical assessment','Assessment remains necessary.'),('Urine culture','It helps identify the pathogen.'),('Evaluation for retention or sepsis','These are important complications to assess.')],
 'Manipulation can worsen bacteremic risk in acute infection', '**Acute prostatitis needs a systemic and urological assessment.**',['Use urine culture and appropriate antimicrobial treatment.','Drug penetration and duration differ from simple bladder infection.'], '**Assess urinary retention and abscess if indicated.**',['Use a safe drainage plan when retention occurs.','Do not apply short uncomplicated-cystitis regimens without considering prostatic involvement.'],[['Avoid','Vigorous massage'],['Investigate','Culture and complications'],['Treatment','Prostate-appropriate agent and duration']],[EA],style='clinical_scenario')
q('An otherwise suitable patient with cUTI improves promptly on an effective non-fluoroquinolone, with source control and no prostatitis or excluded complication. What shorter course does IDSA 2025 suggest?', 'Seven days, counted from the first effective antibiotic day',[
 ('A fixed 21-day course for every cUTI','Longer routine exposure is not necessary in the eligible improving group.'),('One day because fever resolved','This is not the recommended course.'),('The same seven-day rule automatically applies to every abscess or bacterial prostatitis','These groups were commonly excluded from supporting evidence and need individualization.')],
 'Short-course evidence applies to a defined improving population', '**IDSA 2025 suggests seven days for an effective non-fluoroquinolone.**',['A 5–7-day fluoroquinolone course is another suitable-patient option.','Severe sepsis, abscess, obstruction and prostatic disease may change the plan.'], '**Check that the agent was active from the counted start date.**',['Adjust for microbiology and response.','Do not prolong therapy solely because the initial drug was IV.'],[['Eligible non-FQ','Seven days'],['Selected FQ','Five to seven days'],['Exceptions','Complications and excluded populations']],[UT])
q('A cUTI patient is improving on IV treatment, can take oral medication and has an active oral option with suitable tissue exposure. What is appropriate?', 'Consider transition to effective oral therapy rather than maintain IV treatment solely by habit',[
 ('IV therapy must continue for the full course in every cUTI','Selected improving patients can transition.'),('Any oral drug is suitable regardless of susceptibility or tissue exposure','An effective oral option is required.'),('Switch despite uncontrolled obstruction and ongoing shock without reassessment','Clinical stability and source control matter.')],
 'Route can change without sacrificing treatment effectiveness', '**An oral switch can reduce line-related harms.**',['The patient must absorb the medicine and have a suitable agent.','Bacteremic infection requires an option that achieves adequate relevant exposure.'], '**Review source control and clinical response before switching.**',['Use susceptibility-directed dosing.','Provide adherence and follow-up instructions.'],[['Clinical','Improving and able to take oral therapy'],['Drug','Active with adequate exposure'],['Benefit','Avoid unnecessary IV-device risk']],[UT])
q('Urine culture identifies a susceptible organism in an improving cUTI patient. What should happen to unnecessary empirical broad coverage?', 'Narrow to an effective targeted regimen',[
 ('Continue maximal empirical coverage automatically for the full course','This adds avoidable toxicity and resistance pressure.'),('Stop therapy immediately regardless of remaining indicated duration','A suitable definitive course still needs completion.'),('Escalate solely because the culture is positive','Identification should guide precision rather than reflex escalation.')],
 'Culture results should change management when they clarify the target', '**IDSA favors targeted definitive treatment when identification and susceptibility are available.**',['Confirm that the chosen drug reaches the infected site.','Account for allergy and renal function.'], '**Review duration and route together with spectrum.**',['Use a shorter effective course in eligible improving patients.','Reassess persistent symptoms instead of merely extending broad therapy.'],[['Empirical','Risk-based initial breadth'],['Definitive','Targeted active drug'],['Review','Spectrum, route and duration']],[UT])
q('A patient remains febrile after appropriate pyelonephritis therapy and develops persistent focal flank pain. What is the best next principle?', 'Reassess susceptibility and treatment delivery, and image for obstruction or renal/perinephric abscess when indicated',[
 ('Extend the same regimen indefinitely without investigating','An uncontrolled anatomical complication may be present.'),('Assume a positive initial urine culture excludes any complication','It identifies a pathogen, not the whole anatomy.'),('Replace all assessment with repeated urine dipsticks','They do not identify obstruction or a collection.')],
 'Failure to improve should trigger a causal reassessment', '**Persistent infection can reflect resistance, inadequate exposure or an anatomical focus.**',['Ultrasound or CT is selected according to the clinical question.','Abscess or obstruction may need intervention.'], '**Link new testing to a management decision.**',['Review adherence, dose and renal function.','Do not use duration alone to compensate for missing source control.'],[['Drug','Activity and exposure'],['Anatomy','Obstruction or collection'],['Action','Targeted imaging and intervention']],[EA,UT],style='clinical_scenario')
q('Recurrent Proteus urinary infection with alkaline urine raises concern for which associated problem?', 'A urease-associated struvite stone',[
 ('A pure uric-acid stone driven by persistently acidic urine','That is a different chemical setting.'),('A cystine stone established by the organism alone','Cystinuria is a different mechanism.'),('Exclusion of all stone disease because the infection is bacterial','Infection and stones can sustain each other.')],
 'Microbial metabolism can create an anatomical reservoir', '**Urease generates ammonia and raises urinary pH.**',['This favors magnesium ammonium phosphate stone formation.','A stone can support recurrent infection.'], '**Assess the urinary anatomy when the pattern warrants it.**',['Treat the infection and coordinate definitive stone management.','Do not assume repeated antibiotics alone eliminate the reservoir.'],[['Organism','Urease producer'],['Urine','Alkaline'],['Stone','Struvite/infection-associated']],[EA])
q('A patient with diabetes has severe urinary sepsis and CT shows gas in renal parenchyma. Which diagnosis is most concerning?', 'Emphysematous pyelonephritis',[
 ('Simple asymptomatic bacteriuria','It does not explain systemic illness and parenchymal gas.'),('Uncomplicated bladder cystitis','The disease extends beyond the bladder.'),('A benign effect of every urine sample collection','Gas within diseased renal tissue requires urgent assessment.')],
 'Gas-forming renal infection is a high-risk anatomical syndrome', '**Diabetes and obstruction are important risk contexts.**',['CT helps define parenchymal involvement and collections.','A prompt urological and critical-care plan is needed.'], '**Combine antibiotics, resuscitation and source management.**',['Drainage or surgery is selected according to extent and response.','Control metabolic derangements and assess the contralateral kidney.'],[['Imaging','Renal parenchymal gas'],['Risk','Diabetes and obstruction'],['Care','Urgent multidisciplinary management']],[EA],style='clinical_scenario')

if __name__=='__main__':print('Urinary infections: '+str(len(rows))+' questions drafted')
